first(),\r\n\t\t\tdelay(1),\r\n\t\t\tswitchMap(_ => fromEvent(window, 'scroll')),\r\n\t\t\tstartWith(true),\r\n\t\t\t// tap(_ => console.log('ScrollService.scroll')),\r\n\t\t\tmap(_ => {\r\n\t\t\t\t/*\r\n\t\t\t\tconst body = document.querySelector('body');\r\n\t\t\t\tlet previousY = body.scrollTop;\r\n\t\t\t\tbody.addEventListener('scroll', () => {\r\n\t\t\t\t\tconst y = body.scrollTop;\r\n\t\t\t\t\tconst direction = y >= previousY ? 'down' : 'up';\r\n\t\t\t\t\tif (Math.abs(y - previousY) > 90) {\r\n\t\t\t\t\t\t// console.log('scroll', y, direction);\r\n\t\t\t\t\t\tpreviousY = y;\r\n\t\t\t\t\t\tevent.direction = direction;\r\n\t\t\t\t\t\tevent.scroll.y = y;\r\n\t\t\t\t\t\tScrollService.scroll(event);\r\n\t\t\t\t\t}\r\n\t\t\t\t}, true);\r\n\t\t\t\t*/\r\n\t\t\t\tconst y = window.pageYOffset;\r\n\t\t\t\tconst direction = y >= previousY ? 'down' : 'up';\r\n\t\t\t\t// console.log(Math.abs(y - previousY) > 90);\r\n\t\t\t\t// if (Math.abs(y - previousY) > 90) {\r\n\t\t\t\tpreviousY = y;\r\n\t\t\t\tevent.direction = direction;\r\n\t\t\t\tevent.scroll.y = y;\r\n\t\t\t\tScrollService.scroll(event);\r\n\t\t\t\t// }\r\n\t\t\t\treturn event;\r\n\t\t\t}),\r\n\t\t);\r\n\t}\r\n\r\n\tstatic scrollTo(target, options = { offset: -130 }) {\r\n\t\tconst body = document.querySelector('body');\r\n\t\tconst currentTop = body.scrollTop; // window.pageYOffset; // body.scrollTop;\r\n\t\tconst targetTop = currentTop + target.getBoundingClientRect().top + options.offset;\r\n\t\tconst distance = targetTop - currentTop;\r\n\t\tconst o = { pow: 0 };\r\n\t\tgsap.set(body, {\r\n\t\t\t'scroll-behavior': 'auto'\r\n\t\t});\r\n\t\tif (options.disableLerp) {\r\n\t\t\tgsap.set(body, {\r\n\t\t\t\t'scrollTop': currentTop + distance\r\n\t\t\t});\r\n\t\t\tgsap.set(body, {\r\n\t\t\t\t'scroll-behavior': 'smooth'\r\n\t\t\t});\r\n\t\t} else {\r\n\t\t\tgsap.to(o, {\r\n\t\t\t\tduration: Math.abs(distance) / 2000,\r\n\t\t\t\tpow: 1,\r\n\t\t\t\tease: Quad.easeOut,\r\n\t\t\t\toverwrite: 'all',\r\n\t\t\t\tonUpdate: () => {\r\n\t\t\t\t\tgsap.set(body, {\r\n\t\t\t\t\t\t'scrollTop': currentTop + distance * o.pow\r\n\t\t\t\t\t});\r\n\t\t\t\t\t// window.scrollTo(0, currentTop + distance * o.pow);\r\n\t\t\t\t},\r\n\t\t\t\tonComplete: () => {\r\n\t\t\t\t\tgsap.set(body, {\r\n\t\t\t\t\t\t'scroll-behavior': 'smooth'\r\n\t\t\t\t\t});\r\n\t\t\t\t}\r\n\t\t\t});\r\n\t\t}\r\n\t\t// target.scrollIntoView();\r\n\t}\r\n\r\n\tstatic scrollToSelector(selector, options) {\r\n\t\tconst target = document.querySelector(selector);\r\n\t\tif (target) {\r\n\t\t\tScrollService.scrollTo(target, options);\r\n\t\t}\r\n\t}\r\n\r\n}\r\n","import { Component, getContext } from 'rxcomp';\r\nimport { takeUntil } from 'rxjs/operators';\r\nimport { ScrollService } from './common/scroll/scroll.service';\r\n\r\nexport class AppComponent extends Component {\r\n\r\n\tonInit() {\r\n\t\tconst { node } = getContext(this);\r\n\t\tnode.classList.remove('hidden');\r\n\t\tconsole.log('AppComponent.onInit');\r\n\t\tScrollService.init$().pipe(\r\n\t\t\ttakeUntil(this.unsubscribe$),\r\n\t\t).subscribe();\r\n\t}\r\n}\r\n\r\nAppComponent.meta = {\r\n\tselector: '[app-component]',\r\n};\r\n","import { Directive, getContext } from 'rxcomp';\r\n\r\nexport class AltDirective extends Directive {\r\n\r\n\tonChanges() {\r\n\t\tconst { node } = getContext(this);\r\n\t\tnode.setAttribute('alt', this.alt);\r\n\t}\r\n\r\n}\r\n\r\nAltDirective.meta = {\r\n\tselector: '[[alt]]',\r\n\tinputs: ['alt']\r\n};\r\n","import { BehaviorSubject, of, Subject } from 'rxjs';\r\nimport { filter, finalize, map } from 'rxjs/operators';\r\n\r\nexport class IntersectionService {\r\n\r\n\tstatic observer() {\r\n\t\tif (!this.observer_) {\r\n\t\t\tthis.readySubject_ = new BehaviorSubject(false);\r\n\t\t\tthis.observerSubject_ = new Subject();\r\n\t\t\tthis.observer_ = new IntersectionObserver(entries => {\r\n\t\t\t\t// console.log('IntersectionService.observer', entries);\r\n\t\t\t\tthis.observerSubject_.next(entries);\r\n\t\t\t}, {\r\n\t\t\t\t// root: document.q