,EAAA5F,cAAA,2CAA8BoyD,OAOvC,CACA,CACA,SAAKyc,KACL,MAAIjpE,EAAW,WACZ,MAAIvC,EAAAtD,SAAAC,cAAA,oBAAA4jD,GAAA,OAAA,MACGsuB,EAAEnyE,SAAAmyD,eAAAtO,GAAA,OAAA,eACR,OAAAsuB,EACIA,EAAe/f,WAEjB9uD,EACDA,EAAA8uD,WAEJ,IACD,CAVe,GAWb,GAAIvsD,EAAA,CACF,MAAA2sE,EAAA3sE,EAA2B5F,cAAc,mBAC1CuyE,IC59KHC,GAAQz1C,GAGLz/B,GAAuBm1E,G1G2vWxB,CACF,CAKCv3E,EAAOs3E,QAAQz1C,UAAUH,IAC1B,GAAGt/B,QAAQS,KAAKgC,SAAS0yE,uBAAuB,qCAAqC,SAAUC,GAC7FA,EAAiBzkE,iBAAiB,SAAS,WACzC3S,KAAKq3E,cAAchxE,UAAU0gB,OAAO,OACtC,GACF,GAAI","file":"docs\\js\\main.min.js","sourcesContent":[null,"import { fromEvent, ReplaySubject } from 'rxjs';\r\nimport { delay, first, map, startWith, switchMap } from 'rxjs/operators';\r\n\r\nexport class ScrollService {\r\n\r\n\tstatic scroll$ = new ReplaySubject(1);\r\n\tstatic scroll(scroll) {\r\n\t\t// console.log('ScrollService.scroll', scroll);\r\n\t\tthis.scroll$.next(scroll);\r\n\t}\r\n\r\n\tstatic init$(node) {\r\n\t\tlet previousY = window.pageYOffset;\r\n\t\tconst event = { direction: null, scroll: { x: 0, y: 0 }, speed: 0 };\r\n\t\treturn fromEvent(window, 'DOMContentLoaded').pipe(\r\n\t\t\t// tap(_ => console.log('ScrollService.DOMContentLoaded')),\r\n\t\t\tfirst(),\r\n\t\t\tdelay(1),\r\n\t\t\tswitchMap(_ => fromEvent(window, 'scroll')),\r\n\t\t\tstartWith(true),\r\n\t\t\t// tap(_ => console.log('ScrollService.scroll')),\r\n\t\t\tmap(_ => {\r\n\t\t\t\t/*\r\n\t\t\t\tconst body = document.querySelector('body');\r\n\t\t\t\tlet previousY = body.scrollTop;\r\n\t\t\t\tbody.addEventListener('scroll', () => {\r\n\t\t\t\t\tconst y = body.scrollTop;\r\n\t\t\t\t\tconst direction = y >= previousY ? 'down' : 'up';\r\n\t\t\t\t\tif (Math.abs(y - previousY) > 90) {\r\n\t\t\t\t\t\t// console.log('scroll', y, direction);\r\n\t\t\t\t\t\tpreviousY = y;\r\n\t\t\t\t\t\tevent.direction = direction;\r\n\t\t\t\t\t\tevent.scroll.y = y;\r\n\t\t\t\t\t\tScrollService.scroll(event);\r\n\t\t\t\t\t}\r\n\t\t\t\t}, true);\r\n\t\t\t\t*/\r\n\t\t\t\tconst y = window.pageYOffset;\r\n\t\t\t\tconst direction = y >= previousY ? 'down' : 'up';\r\n\t\t\t\t// console.log(Math.abs(y - previousY) > 90);\r\n\t\t\t\t// if (Math.abs(y - previousY) > 90) {\r\n\t\t\t\tpreviousY = y;\r\n\t\t\t\tevent.direction = direction;\r\n\t\t\t\tevent.scroll.y = y;\r\n\t\t\t\tScrollService.scroll(event);\r\n\t\t\t\t// }\r\n\t\t\t\treturn event;\r\n\t\t\t}),\r\n\t\t);\r\n\t}\r\n\r\n\tstatic scrollTo(target, options = { offset: -130 }) {\r\n\t\tconst body = document.querySelector('body');\r\n\t\tconst currentTop = body.scrollTop; // window.pageYOffset; // body.scrollTop;\r\n\t\tconst targetTop = currentTop + target.getBoundingClientRect().top + options.offset;\r\n\t\tconst distance = targetTop - currentTop;\r\n\t\tconst o = { pow: 0 };\r\n\t\tgsap.set(body, {\r\n\t\t\t'scroll-behavior': 'auto'\r\n\t\t});\r\n\t\tif (options.disableLerp) {\r\n\t\t\tgsap.set(body, {\r\n\t\t\t\t'scrollTop': currentTop + distance\r\n\t\t\t});\r\n\t\t\tgsap.set(body, {\r\n\t\t\t\t'scroll-behavior': 'smooth'\r\n\t\t\t});\r\n\t\t} else {\r\n\t\t\tgsap.to(o, {\r\n\t\t\t\tduration: Math.abs(distance) / 2000,\r\n\t\t\t\tpow: 1,\r\n\t\t\t\tease: Quad.easeOut,\r\n\t\t\t\toverwrite: 'all',\r\n\t\t\t\tonUpdate: () => {\r\n\t\t\t\t\tgsap.set(body, {\r\n\t\t\t\t\t\t'scrollTop': currentTop + distance * o.pow\r\n\t\t\t\t\t});\r\n\t\t\t\t\t// window.scrollTo(0, currentTop + distance * o.pow);\r\n\t\t\t\t},\r\n\t\t\t\tonComplete: () => {\r\n\t\t\t\t\tgsap.set(body, {\r\n\t\t\t\t\t\t'scroll-behavior': 'smooth'\r\n\t\t\t\t\t});\r\n\t\t\t\t}\r\n\t\t\t});\r\n\t\t}\r\n\t\t// target.scrollIntoView();\r\n\t}\r\n\r\n\tstatic scrollToSelector(selector, options) {\r\n\t\tconst target = document.querySelector(selector);\r\n\t\tif (target) {\r\n\t\t\tScrollService.scrollTo(target, options);\r\n\t\t}\r\n\t}\r\n\r\n}\r\n","import { Component, getContext } from 'rxcomp';\r\nimport { takeUntil } from 'rxjs/operators';\r\nimport { ScrollService } from './common/scroll/scroll.service';\r\n\r\nexport class AppComponent extends Component {\r\n\r\n\tonInit() {\r\n\t\tconst { node } = getContext(this);\r\n\t\tnode.classList.remove('hidden');\r\n\t\tconsole.log('AppComponent.onInit');\r\n\t\tScrollService.init$().pipe(\r\n\t\t\ttakeUntil(this.unsubscribe$),\r\n\t\t).subscribe();\r\n\t}\r\n}\r\n\r\nAppComponent.meta = {\r\n\tselector: '[app-component]',\r\n};\r\n","import { Directive, getContext } from 'rxcomp';\r\n\r\nexport class AltDirective extends Directive {\r\n\r\n\tonChanges() {\r\n\t\tconst { node } = getContext(this);\r\n\t\tnode.setAttribute('alt', this.alt);\r\n\t}\r\n\r\n}\r\n\r\nAltDirective.meta = {\r\n\tselector: '[[alt]]',\r\n\tinputs: ['alt']\r\n};\r\n","import { BehaviorSubject, of, Subject } from 'rxjs';\r\nimport { filter, finalize, map } from 'rxjs/operators';\r\n\r\nexport class IntersectionService {\r\n\r\n\tstatic observer() {\r\n\t\tif (!this.observer_) {\r\n\t\t\tthis.readySubject_ = new BehaviorSubject(false);\r\n\t\t\tthis.observerSubject_ = new Subject();\r\n\t\t\tthis.observer_ = new IntersectionObserver(entries => {\r\n\t\t\t\t// console.log('IntersectionService.observer', entries);\r\n\t\t\t\tthis.observerSubject_.next(entries);\r\n\t\t\t}, {\r\n\t\t\t\t// root: document.querySelector('body'),\r\n\t\t\t\troot: null, // sets the framing element to the viewport\r\n\t\t\t\trootMargin: '100px 0px 100px 0px',\r\n\t\t\t\tthreshold: [0, 0.25, 0.5, 0.75, 1],\r\n\t\t\t});\r\n\t\t}\r\n\t\treturn this.observer_;\r\n\t}\r\n\r\n\tstatic intersection$(node) {\r\n\t\tif ('IntersectionObserver' in window) {\r\n\t\t\tconst observer = this.observer();\r\n\t\t\tobserver.observe(node);\r\n\t\t\treturn this.observerSubject_.pipe(\r\n\t\t\t\t// tap(entries => console.log(entries.length)),\r\n\t\t\t\tmap(entries => entries.find(entry => entry.target === node)),\r\n\t\t\t\t// tap(entry => console.log('IntersectionService.intersection$', entry)),\r\n\t\t\t\tfilter(entry => entry !== undefined),\r\n\t\t\t\t// filter(entry => entry !== undefined && entry.isIntersecting && entry.intersectionRatio > 0), // entry.intersectionRatio > 0\r\n\t\t\t\t// first(),\r\n\t\t\t\tfinalize(() => observer.unobserve(node)),\r\n\t\t\t);\r\n\t\t} else {\r\n\t\t\treturn of({ target: node });\r\n\t\t}\r\n\r\n\t\t/*\r\n\t\tfunction observer() {\r\n\t\t\tif ('IntersectionObserver' in window) {\r\n\t\t\t\treturn new IntersectionObserver(entries => {\r\n\t\t\t\t\tentries.forEach(function(entry) {\r\n\t\t\t\t\t\tif (entry.isIntersecting) {\r\n\t\t\t\t\t\t\tentry.target.classList.add('appear');\r\n\t\t\t\t\t\t}\r\n\t\t\t\t\t})\r\n\t\t\t\t});\r\n\t\t\t} else {\r\n\t\t\t\treturn { observe: function(node) { node.classList.add('appear')}, unobserve: function() {} };\r\n\t\t\t}\r\n\t\t}\r\n\t\tobserver.observe(node);\r\n\t\tobserver.unobserve(node);\r\n\t\t*/\r\n\r\n\t}\r\n\r\n}\r\n","import { Directive, getContext } from 'rxcomp';\r\nimport { takeUntil } from 'rxjs/operators';\r\nimport { IntersectionService } from '../intersection/intersection.service';\r\n\r\nexport class AppearDirective extends Directive {\r\n\r\n\tonInit() {\r\n\t\tconst { node } = getContext(this);\r\n\t\tnode.classList.add('appear');\r\n\t\tIntersectionService.intersection$(node).pipe(\r\n\t\t\t// first(),\r\n\t\t\ttakeUntil(this.unsubscribe$),\r\n\t\t).subscribe(entry => {\r\n\t\t\tentry.intersectionRatio > 0.5 ? node.classList.add('appeared') : node.classList.remove('appeared');\r\n\t\t});\r\n\t}\r\n\r\n}\r\n\r\nAppearDirective.meta = {\r\n\tselector: '[appear]',\r\n};\r\n","import { Directive, getContext } from 'rxcomp';\r\nimport { fromEvent } from 'rxjs';\r\nimport { filter, shareReplay, takeUntil } from 'rxjs/operators';\r\n\r\nexport class ClickOutsideDirective extends Directive {\r\n\r\n\tonInit() {\r\n\t\tthis.initialFocus = false;\r\n\t\tconst { module, node, parentInstance, selector } = getContext(this);\r\n\t\tconst event$ = this.event$ = fromEvent(document, 'click').pipe(\r\n\t\t\tfilter(event => {\r\n\t\t\t\tconst target = event.target;\r\n\t\t\t\t// console.log('ClickOutsideDirective.onClick', this.element.nativeElement, target, this.element.nativeElement.contains(target));\r\n\t\t\t\t// const documentContained: boolean = Boolean(document.compareDocumentPosition(target) & Node.DOCUMENT_POSITION_CONTAINED_BY);\r\n\t\t\t\t// console.log(target, documentContained);\r\n\t\t\t\tconst clickedInside = node.contains(target) || !document.contains(target);\r\n\t\t\t\tif (!clickedInside) {\r\n\t\t\t\t\tif (this.initialFocus) {\r\n\t\t\t\t\t\tthis.initialFocus = false;\r\n\t\t\t\t\t\treturn true;\r\n\t\t\t\t\t}\r\n\t\t\t\t} else {\r\n\t\t\t\t\tthis.initialFocus = true;\r\n\t\t\t\t}\r\n\t\t\t}),\r\n\t\t\tshareReplay(1)\r\n\t\t);\r\n\t\tconst expression = node.getAttribute(`(clickOutside)`);\r\n\t\tif (expression) {\r\n\t\t\tconst outputFunction = module.makeFunction(expression, ['$event']);\r\n\t\t\tevent$.pipe(\r\n\t\t\t\ttakeUntil(this.unsubscribe$),\r\n\t\t\t).subscribe(event => {\r\n\t\t\t\tmodule.resolve(outputFunction, parentInstance, event);\r\n\t\t\t});\r\n\t\t} else {\r\n\t\t\tparentInstance.clickOutside$ = event$;\r\n\t\t}\r\n\t}\r\n\r\n}\r\n\r\nClickOutsideDirective.meta = {\r\n\tselector: `[(clickOutside)]`,\r\n};\r\n","\r\nexport class Utils {\r\n\r\n\tstatic merge(target, source) {\r\n\t\tif (typeof source === 'object') {\r\n\t\t\tObject.keys(source).forEach(key => {\r\n\t\t\t\tconst value = source[key];\r\n\t\t\t\tif (typeof value === 'object' && !Array.isArray(value)) {\r\n\t\t\t\t\ttarget[key] = this.merge(target[key], value);\r\n\t\t\t\t} else {\r\n\t\t\t\t\ttarget[key] = value;\r\n\t\t\t\t}\r\n\t\t\t});\r\n\t\t}\r\n\t\treturn target;\r\n\t}\r\n\r\n}\r\n","import { Utils } from './common/utils/utils';\r\nimport { environmentServed } from './environment.served';\r\nimport { environmentStatic } from './environment.static';\r\n\r\nexport const NODE = (typeof module !== 'undefined' && module.exports);\r\nexport const PARAMS = NODE ? { get: () => { } } : new URLSearchParams(window.location.search);\r\nexport const DEBUG = false || (PARAMS.get('debug') != null);\r\nexport const BA