t\tthis.load$().pipe(\r\n\t\t\tfirst(),\r\n\t\t).subscribe();\r\n\t}\r\n\r\n\tload$() {\r\n\t\treturn ContactsService.data$().pipe(\r\n\t\t\ttap(data => {\r\n\t\t\t\tconst controls = this.controls;\r\n\t\t\t\tcontrols.country.options = FormService.toSelectOptions(data.country.options);\r\n\t\t\t\t//if (this.countryId) {\r\n\t\t\t\t//\tthis.form.patch({\r\n\t\t\t\t//\t\tcountry: this.countryId,\r\n\t\t\t\t//\t});\r\n\t\t\t\t//}\r\n\t\t\t\tthis.pushChanges();\r\n\t\t\t})\r\n\t\t);\r\n\t}\r\n\r\n\ttest() {\r\n\t\tconst form = this.form;\r\n\t\tconst controls = this.controls;\r\n\t\tconst country = controls.country.options.length > 1 ? controls.country.options[1].id : null;\r\n\t\tform.patch({\r\n\t\t\tfirstName: 'Jhon',\r\n\t\t\tlastName: 'Appleseed',\r\n\t\t\tcompany: 'Websolute',\r\n\t\t\taddress: 'Strada della Campanara, 15',\r\n\t\t\tcity: 'Pesaro',\r\n\t\t\tzip: 61122,\r\n\t\t\tcountry: country,\r\n\t\t\temail: 'jhonappleseed@gmail.com',\r\n\t\t\tsubject: 'Subject',\r\n\t\t\tmessage: 'Hi!',\r\n\t\t\tprivacy: true,\r\n\t\t\tcheckRequest: window.antiforgery,\r\n\t\t\tcheckField: ''\r\n\t\t});\r\n\t}\r\n\r\n\treset() {\r\n\t\tconst form = this.form;\r\n\t\tform.reset();\r\n\t}\r\n\r\n\tonSubmit(model) {\r\n\t\tconst form = this.form;\r\n\t\tconsole.log('ContactModalComponent.onSubmit', form.value);\r\n\t\t// console.log('ContactModalComponent.onSubmit', 'form.valid', valid);\r\n\t\tif (form.valid) {\r\n\t\t\t// console.log('ContactModalComponent.onSubmit', form.value);\r\n\t\t\tform.submitted = true;\r\n\t\t\tContactsService.submit$(form.value).pipe(\r\n\t\t\t\tfirst(),\r\n\t\t\t).subscribe(_ => {\r\n\t\t\t\tif (_.success) {\r\n\t\t\t\t\tGtmService.push({ 'event': \"Contact\", 'form_name': \"Contatti\" });\r\n\t\t\t\t}\r\n\t\t\t\tthis.success = true;\r\n\t\t\t\tform.reset();\r\n\t\t\t\tthis.response = _.data[\"response\"];\r\n\t\t\t\tthis.message = _.data[\"message\"];\r\n\t\t\t}, error => {\r\n\t\t\t\tconsole.log('ContactModalComponent.error', error);\r\n\t\t\t\tthis.error = error;\r\n\t\t\t\tthis.pushChanges();\r\n\t\t\t});\r\n\t\t} else {\r\n\t\t\tform.touched = true;\r\n\t\t}\r\n\t}\r\n\r\n\tonClose() {\r\n\t\tModalService.reject();\r\n\t}\r\n}\r\n\r\nContactModalComponent.meta = {\r\n\tselector: '[contact-modal]',\r\n\tinputs: [],\r\n};\r\n","import { Directive, getContext } from 'rxcomp';\r\nimport { fromEvent } from 'rxjs';\r\nimport { first, takeUntil, tap } from 'rxjs/operators';\r\nimport { ModalService } from '../../common/modal/modal.service';\r\nimport { environment } from '../../environment';\r\n\r\nexport class OpenModallyDirective extends Directive {\r\n\r\n\tonInit() {\r\n\t\tconst { node } = getContext(this);\r\n\t\tconst selector = node.getAttribute('open-modally');\r\n\t\tlet target = document.querySelector(selector);\r\n\t\tif (target) {\r\n\t\t\ttarget = target.cloneNode(true);\r\n\t\t\t// target.parentNode.removeChild(target);\r\n\t\t\tthis.click$(target).pipe(\r\n\t\t\t\ttakeUntil(this.unsubscribe$),\r\n\t\t\t).subscribe();\r\n\t\t}\r\n\t}\r\n\r\n\tclick$(target) {\r\n\t\tconst { node, module } = getContext(this);\r\n\t\treturn fromEvent(node, 'click').pipe(\r\n\t\t\ttap(_ => {\r\n\t\t\t\tModalService.open$({ src: environment.template.modal.sideModal, data: { target: target.cloneNode(true) } }).pipe(\r\n\t\t\t\t\tfirst(),\r\n\t\t\t\t).subscribe(event => {\r\n\t\t\t\t\tconsole.log('OpenModallyDirective.open$', event);\r\n\t\t\t\t});\r\n\t\t\t}),\r\n\t\t);\r\n\t}\r\n\r\n}\r\n\r\nOpenModallyDirective.meta = {\r\n\tselector: '[open-modally]'\r\n};\r\n","import { ApiService } from '../../common/api/api.service';\r\nimport { environment } from '../../environment';\r\n\r\nexport class ProductRequestService {\r\n\r\n\tstatic data$() {\r\n\t\tif (environment.flags.production) {\r\n\t\t\treturn ApiService.get$('/wp-json/aquafil/v1/countries?page=' + ws_vars.post_id);\r\n\t\t} else {\r\n\t\t\treturn ApiService.get$('/contacts/data.json');\r\n\t\t}\r\n\t}\r\n\r\n\tstatic submit$(payload) {\r\n\t\tif (environment.flags.production) {\r\n\t\t\treturn ApiService.http$('POST', environment.api + '/wp-admin/admin-ajax.php', payload, 'application/x-www-form-urlencoded');\r\n\t\t} else {\r\n\t\t\treturn ApiService.get$('/contacts/submit.json');\r\n\t\t}\r\n\t}\r\n\r\n}\r\n","import { Component, getContext } from 'rxcomp';\r\nimport { FormControl, FormGroup, Validators } from 'rxcomp-form';\r\nimport { first, takeUntil, tap } from 'rxjs/operators';\r\nimport { GtmService } from '../../common/gtm/gtm.service';\r\nimport { ModalOutletComponent } from '../../common/modal/modal-outlet.component';\r\nimport { ModalService } from '../../common/modal/modal.service';\r\nimport { FormService } from '../../controls/form.service';\r\nimport { ProductRequestService } from './product-request.service';\r\n\r\nexport class ProductRequestComponent extends Component {\r\n\r\n\tonInit() {\r\n\t\tconst { parentInstance } = getContext(this);\r\n\t\tif (parentInstance instanceof ModalOutletComponent) {\r\n\t\t\tconst data = parentInstance.modal.data;\r\n\t\t\tconst id = data.id;\r\n\t\t\tconst productName = data.productName;\r\n\t\t\tthis.productName = productName ? productName : this.productName;\r\n\t\t\tconst recipient = data.recipient;\r\n\t\t\tthis.recipient = recipient ? recipient : this.recipient;\r\n\t\t\tconst download = data.download;\r\n\t\t\tthis.download = download ? download : this.download;\r\n\t\t\tconsole.log('ProductRequestComponent.onInit', id, productName);\r\n\t\t}\r\n\t\tthis.error = null;\r\n\t\tthis.success = false;\r\n\t\tthis.response = '';\r\n\t\tthis.message = '';\r\n\t\tconst form = this.form = new FormGroup({\r\n\t\t\tproductName: this.productName,\r\n\t\t\trecipient: this.recipient,\r\n\t\t\tdownload: this.download,\r\n\t\t\tfirstName: new FormControl(null, [Validators.RequiredValidator()]),\r\n\t\t\tlastName: new FormControl(null, [Validators.RequiredValidator()]),\r\n\t\t\t// company: new FormControl(null),\r\n\t\t\tcountry: new FormControl(null, [Validators.RequiredValidator()]),\r\n\t\t\temail: new FormControl(null, [Validators.RequiredValidator(), Validators.EmailValidator()]),\r\n\t\t\tsubject: new FormControl(null, [Validators.RequiredValidator()]),\r\n\t\t\tmessage: new FormControl(null, [Validators.RequiredValidator()]),\r\n\t\t\tprivacy: new FormControl(null, [Validators.RequiredTrueValidator()]),\r\n\t\t\tcheckRequest: window.antiforgery,\r\n\t\t\tcheckField: '',\r\n\t\t\taction: 'save_product_request',\r\n\t\t});\r\n\t\tconst controls = this.controls = form.controls;\r\n\t\tform.changes$.pipe(\r\n\t\t\ttakeUntil(this.unsubscribe$)\r\n\t\t).subscribe((_) => {\r\n\t\t\tthis.pushChanges();\r\n\t\t});\r\n\t\tthis.load$().pipe(\r\n\t\t\tfirst(),\r\n\t\t).subscribe();\r\n\t}\r\n\r\n\tload$() {\r\n\t\treturn ProductRequestService.data$().pipe(\r\n\t\t\ttap(data => {\r\n\t\t\t\tconst controls = this.controls;\r\n\t\t\t\tcontrols.country.options = FormService.toSelectOptions(data.country.options);\r\n\t\t\t\t//if (this.countryId) {\r\n\t\t\t\t//\tthis.form.patch({\r\n\t\t\t\t//\t\tcountry: this.countryId,\r\n\t\t\t\t//\t});\r\n\t\t\t\t//}\r\n\t\t\t\tthis.pushChanges();\r\n\t\t\t})\r\n\t\t);\r\n\t}\r\n\r\n\ttest() {\r\n\t\tconst form = this.form;\r\n\t\tconst controls = this.controls;\r\n\t\tform.patch({\r\n\t\t\tfirstName: 'Jhon',\r\n\t\t\tlastName: 'Appleseed',\r\n\t\t\tcompany: 'Websolute',\r\n\t\t\temail: 'jhonappleseed@gmail.com',\r\n\t\t\tsubject: 'Subject',\r\n\t\t\tmessage: 'Hi!',\r\n\t\t\tprivacy: true,\r\n\t\t\tcheckRequest: window.antiforgery,\r\n\t\t\tcheckField: ''\r\n\t\t});\r\n\t}\r\n\r\n\treset() {\r\n\t\tconst form = this.form;\r\n\t\tform.reset();\r\n\t}\r\n\r\n\tonSubmit(model) {\r\n\t\tconst form = this.form;\r\n\t\tconsole.log('ProductRequestComponent.onSubmit', form.value);\r\n\t\t// console.log('ProductRequestComponent.onSubmit', 'form.valid', valid);\r\n\t\tif (form.valid) {\r\n\t\t\t// console.log('ProductRequestComponent.onSubmit', form.value);\r\n\t\t\tform.submitted = true;\r\n\t\t\tProductRequestService.submit$(form.value).pipe(\r\n\t\t\t\tfirst(),\r\n\t\t\t).subscribe(_ => {\r\n\t\t\t\tif (_.success) {\r\n\t\t\t\t\tGtmService.push({ 'event': \"Product Request\", 'form_name': \"Product Request\" });\r\n\t\t\t\t}\r\n\t\t\t\tthis.success = true;\r\n\t\t\t\tform.reset();\r\n\t\t\t\tthis.response = _.data[\"response\"];\r\n\t\t\t\tthis.message = _.data[\"message\"];\r\n\t\t\t}, error => {\r\n\t\t\t\tconsole.log('ProductRequestComponent.error', error);\r\n\t\t\t\tthis.error = error;\r\n\t\t\t\tthis.pushChanges();\r\n\t\t\t});\r\n\t\t} else {\r\n\t\t\tform.touched = true;\r\n\t\t}\r\n\t}\r\n\r\n\tonClose() {\r\n\t\tModalService.reject();\r\n\t}\r\n}\r\n\r\nProductRequestComponent.meta = {\r\n\tselector: '[product-request]',\r\n\tinputs: ['productName', 'download'],\r\n};\r\n","import { Component } from 'rxcomp';\r\n\r\nexport class ProductListComponent extends Component {\r\n\tonInit() {\r\n\t\tthis.activeFilters = new Set();\r\n\t\tthis.currentCategory = 'all';\r\n\t\tthis.visibleItemsCount = 10;\r\n\t\tthis.itemsPerLoad = 5;\r\n\t\tthis.filteredCards = [];\r\n\t\tthis.initializeFilters();\r\n\t\tthis.initializeSidebarFilters();\r\n\t\tthis.updateFilterCounts();\r\n\t\tthis.initializeLoadMore();\r\n\t\tthis.applyCardVisibility();\r\n\t}\r\n\r\n\tinitializeSidebarFilters() {\r\n\t\tconst sidebarButtons = document.querySelectorAll('.product-list__sidebar .list-filters .btn');\r\n\r\n\t\tsidebarButtons.forEach(button => {\r\n\t\t\tbutton.addEventListener('click', (event) => {\r\n\t\t\t\tconst filterText = event.target.textContent.trim();\r\n\r\n\t\t\t\t// Toggle active state of the button\r\n\t\t\t\tbutton.classList.toggle('active');\r\n\r\n\t\t\t\tif (button.classList.contains('active')) {\r\n\t\t\t\t\tthis.activeFilters.add(filterText);\r\n\t\t\t\t} else {\r\n\t\t\t\t\tthis.activeFilters.delete(filterText);\r\n\t\t\t\t}\r\n\r\n\t\t\t\tthis.filterCards();\r\n\t\t\t});\r\n\t\t});\r\n\t}\r\n\tfilterCards() {\r\n\t\tconst cards = document.querySelectorAll('.card--calendar');\r\n\t\tconst noResultsDiv = document.querySelector('.no-results');\r\n\r\n\t\t// Reset visibility counter when applying filters\r\n\t\tthis.visibleItemsCount = 10;\r\n\r\n\t\t// Get filtered cards first\r\n\t\tthis.filteredCards = [];\r\n\r\n\t\tcards.forEach(card => {\r\n\t\t\t// Prima controlla se la card appartiene alla categoria corrente\r\n\t\t\tconst matchesCategory = this.currentCategory === 'all' || card.classList.contains(this.currentCategory);\r\n\r\n\t\t\t// Se non appartiene alla categoria, nascondi la card\r\n\t\t\tif (!matchesCategory) {\r\n\t\t\t\tcard.style.display = 'none';\r\n\t\t\t\treturn;\r\n\t\t\t}\r\n\r\n\t\t\t// Se non ci sono filtri attivi nella sidebar e la card appartiene alla categoria\r\n\t\t\tif (this.activeFilters.size === 0) {\r\n\t\t\t\tthis.filteredCards.push(card);\r\n\t\t\t\treturn;\r\n\t\t\t}\r\n\r\n\t\t\t// Controlla i tag della card\r\n\t\t\tconst tagList = card.querySelector('.tag-list');\r\n\t\t\tconst tags = tagList ? Array.from(tagList.querySelectorAll('.btn')).map(tag => tag.textContent.trim()) : [];\r\n\r\n\t\t\t// Check if any of the card's tags match any of the active filters\r\n\t\t\tconst hasMatchingTag = Array.from(this.activeFilters).some(filter => {\r\n\t\t\t\t// Handle comma-separated tags (like \"Filled, Impact Modified, Colored\")\r\n\t\t\t\tconst cardTagsExpanded = tags.reduce((acc, tag) => {\r\n\t\t\t\t\treturn acc.concat(tag.split(', '));\r\n\t\t\t\t}, []);\r\n\r\n\t\t\t\treturn cardTagsExpanded.includes(filter);\r\n\t\t\t});\r\n\r\n\t\t\tif (hasMatchingTag) {\r\n\t\t\t\tthis.filteredCards.push(card);\r\n\t\t\t} else {\r\n\t\t\t\tcard.style.display = 'none';\r\n\t\t\t}\r\n\t\t});\r\n\r\n\t\t// Mostra/nascondi il messaggio \"nessun risultato\"\r\n\t\tif (this.filteredCards.length === 0) {\r\n\t\t\tnoResultsDiv.style.display = 'block';\r\n\t\t\t// Nascondi anche il pulsante \"Carica altro\" quando non ci sono risultati\r\n\t\t\tconst loadMoreBtn = document.querySelector('.load-more-btn');\r\n\t\t\tif (loadMoreBtn) loadMoreBtn.classList.add('hidden');\r\n\t\t} else {\r\n\t\t\tnoResultsDiv.style.display = 'none';\r\n\t\t}\r\n\r\n\t\t// Apply visibility based on current visible items count\r\n\t\tthis.applyCardVisibility();\r\n\r\n\t\t// Update the load more button\r\n\t\tthis.updateLoadMoreButton();\r\n\t}\r\n\r\n\tupdateFilterCounts() {\r\n\t\t// Get all cards\r\n\t\tconst allCards = document.querySelectorAll('.card--calendar');\r\n\t\tconst basedPolymerCards = document.querySelectorAll('.card--calendar.based-polymer');\r\n\t\tconst engineeredPolymerCards = document.querySelectorAll('.card--calendar.engineered-polymers');\r\n\r\n\t\t// Update count numbers in the filter menu\r\n\t\tconst allCountEl = document.querySelector('.history-filter[data-filter=\"all\"] .count');\r\n\t\tconst basedPolymerCountEl = document.querySelector('.history-filter[data-filter=\"based-polymer\"] .count');\r\n\t\tconst engineeredPolymerCountEl = document.querySelector('.history-filter[data-filter=\"engineered-polymers\"] .count');\r\n\r\n\t\tif (allCountEl) allCountEl.textContent = `(${allCards.length})`;\r\n\t\tif (basedPolymerCountEl) basedPolymerCountEl.textContent = `(${basedPolymerCards.length})`;\r\n\t\tif (engineeredPolymerCountEl) engineeredPolymerCountEl.textContent = `(${engineeredPolymerCards.length})`;\r\n\t}\r\n\r\n\ttoggleSidebarSections(categoryFilter) {\r\n\t\t// Trova l'elemento della sidebar con le sezioni based polymer e engineered polymers\r\n\t\tconst propertiesContent = document.querySelector('.sidebar--item.properties .sidebar--content');\r\n\t\tif (!propertiesContent) return;\r\n\r\n\t\t// Trova le sezioni in base ai loro titoli\r\n\t\tconst sections = propertiesContent.querySelectorAll('.filters-title');\r\n\t\tlet basedPolymerSection = null;\r\n\t\tlet engineeredPolymerSection = null;\r\n\r\n\t\tsections.forEach(section => {\r\n\t\t\tconst title = section.textContent.trim().toLowerCase();\r\n\t\t\tif (title === 'based polymer') {\r\n\t\t\t\tbasedPolymerSection = section;\r\n\t\t\t} else if (title === 'engineered polymers') {\r\n\t\t\t\tengineeredPolymerSection = section;\r\n\t\t\t}\r\n\t\t});\r\n\r\n\t\tif (basedPolymerSection && engineeredPolymerSection) {\r\n\t\t\t// Ottieni gli elementi filters che seguono ciascun titolo\r\n\t\t\tconst getNextFilters = (element) => {\r\n\t\t\t\tlet nextElement = element.nextElementSibling;\r\n\t\t\t\tif (nextElement && nextElement.classList.contains('list-filters')) {\r\n\t\t\t\t\treturn nextElement;\r\n\t\t\t\t}\r\n\t\t\t\treturn null;\r\n\t\t\t};\r\n\r\n\t\t\tconst basedPolymerFilters = getNextFilters(basedPolymerSection);\r\n\t\t\tconst engineeredPolymerFilters = getNextFilters(engineeredPolymerSection);\r\n\r\n\t\t\t// Rimuovi tutte le classi hide-section\r\n\t\t\tif (basedPolymerSection) basedPolymerSection.classList.remove('hide-section');\r\n\t\t\tif (basedPolymerFilters) basedPolymerFilters.classList.remove('hide-section');\r\n\t\t\tif (engineeredPolymerSection) engineeredPolymerSection.classList.remove('hide-section');\r\n\t\t\tif (engineeredPolymerFilters) engineeredPolymerFilters.classList.remove('hide-section');\r\n\r\n\t\t\t// Aggiungi le classi hide-section in base al filtro selezionato\r\n\t\t\tif (categoryFilter === 'based-polymer') {\r\n\t\t\t\t// Nascondi sezione engineered polymers\r\n\t\t\t\tif (engineeredPolymerSection) engineeredPolymerSection.classList.add('hide-section');\r\n\t\t\t\tif (engineeredPolymerFilters) engineeredPolymerFilters.classList.add('hide-section');\r\n\t\t\t}\r\n\t\t\telse if (categoryFilter === 'engineered-polymers') {\r\n\t\t\t\t// Nascondi sezione based polymer\r\n\t\t\t\tif (basedPolymerSection) basedPolymerSection.classList.add('hide-section');\r\n\t\t\t\tif (basedPolymerFilters) basedPolymerFilters.classList.add('hide-section');\r\n\t\t\t}\r\n\t\t}\r\n\t}\r\n\r\n\tinitializeFilters() {\r\n\t\tconst filters = document.querySelectorAll('.history-filter');\r\n\t\tfilters.forEach(filter => {\r\n\t\t\tfilter.addEventListener('click', (event) => {\r\n\t\t\t\t// Remove active class from all filters\r\n\t\t\t\tfilters.forEach(f => f.classList.remove('active'));\r\n\r\n\t\t\t\t// Add active class to clicked filter\r\n\t\t\t\tconst filterEl = event.target.closest('.history-filter');\r\n\t\t\t\tfilterEl.classList.add('active');\r\n\r\n\t\t\t\t// Get and store the filter value\r\n\t\t\t\tthis.currentCategory = filterEl.getAttribute('data-filter');\r\n\r\n\t\t\t\t// Nascondi/mostra sezioni appropriate nella sidebar\r\n\t\t\t\tthis.toggleSidebarSections(this.currentCategory);\r\n\r\n\t\t\t\t// Apply filters\r\n\t\t\t\tthis.filterCards();\r\n\t\t\t});\r\n\t\t});\r\n\r\n\t\t// Ensure \"All\" filter is active by default\r\n\t\tconst allFilter = document.querySelector('.history-filter[data-filter=\"all\"]');\r\n\t\tif (allFilter) {\r\n\t\t\tallFilter.classList.add('active');\r\n\t\t\t// Mostra tutte le sezioni della sidebar all'inizio\r\n\t\t\tthis.toggleSidebarSections('all');\r\n\t\t}\r\n\t}\r\n\r\n\tinitializeLoadMore() {\r\n\t\t// Inizializza il pulsante \"Carica altro\"\r\n\t\tconst loadMoreBtn = document.querySelector('.load-more-btn');\r\n\r\n\t\tif (loadMoreBtn) {\r\n\t\t\tloadMoreBtn.addEventListener('click', () => {\r\n\t\t\t\tthis.loadMoreItems();\r\n\t\t\t});\r\n\r\n\t\t\t// Impostazione iniziale del pulsante\r\n\t\t\tthis.updateLoadMoreButton();\r\n\t\t}\r\n\t}\r\n\r\n\tloadMoreItems() {\r\n\t\t// Aggiunge altri elementi alla vista\r\n\t\tthis.visibleItemsCount += this.itemsPerLoad;\r\n\t\tthis.applyCardVisibility();\r\n\t\tthis.updateLoadMoreButton();\r\n\t}\r\n\tapplyCardVisibility() {\r\n\t\t// Applica la visibilità alle card in base all'indice\r\n\t\tconst cards = this.filteredCards.length > 0 ? this.filteredCards : document.querySelectorAll('.card--calendar');\r\n\t\tconst noResultsVisible = document.querySelector('.no-results').style.display === 'block';\r\n\r\n\t\t// Se il messaggio \"nessun risultato\" è visibile, nascondi tutte le cards\r\n\t\tif (noResultsVisible) {\r\n\t\t\tcards.forEach(card => {\r\n\t\t\t\tcard.style.display = 'none';\r\n\t\t\t});\r\n\t\t\treturn;\r\n\t\t}\r\n\r\n\t\t// Altrimenti, applica la logica di visibilità in base all'indice\r\n\t\tcards.forEach((card, index) => {\r\n\t\t\tif (index < this.visibleItemsCount) {\r\n\t\t\t\tcard.style.display = 'flex';\r\n\t\t\t} else {\r\n\t\t\t\tcard.style.display = 'none';\r\n\t\t\t}\r\n\t\t});\r\n\t}\r\n\tupdateLoadMoreButton() {\r\n\t\tconst loadMoreBtn = document.querySelector('.load-more-btn');\r\n\t\tif (!loadMoreBtn) return;\r\n\r\n\t\tconst filteredCards = this.filteredCards.length > 0 ? this.filteredCards : document.querySelectorAll('.card--calendar');\r\n\t\tconst noResultsVisible = document.querySelector('.no-results').style.display === 'block';\r\n\r\n\t\t// Nascondi il pulsante se il messaggio \"no results\" è visibile o non ci sono altre card da mostrare\r\n\t\tif (noResultsVisible || filteredCards.length <= this.visibleItemsCount) {\r\n\t\t\tloadMoreBtn.classList.add('hidden');\r\n\t\t} else {\r\n\t\t\tloadMoreBtn.classList.remove('hidden');\r\n\t\t}\r\n\t}\r\n}\r\n\r\nProductListComponent.meta = {\r\n\tselector: '[product-list]'\r\n};\r\n","import { Component, getContext } from 'rxcomp';\r\nimport { FormControl, FormGroup, Validators } from 'rxcomp-form';\r\nimport { first, takeUntil, tap } from 'rxjs/operators';\r\nimport { GtmService } from '../../common/gtm/gtm.service';\r\nimport { ModalOutletComponent } from '../../common/modal/modal-outlet.component';\r\nimport { ModalService } from '../../common/modal/modal.service';\r\nimport { FormService } from '../../controls/form.service';\r\nimport { SalesService } from './sales.service';\r\n\r\nexport class SalesModalComponent extends Component {\r\n\r\n\tonInit() {\r\n\t\tconst { parentInstance } = getContext(this);\r\n\t\tif (parentInstance instanceof ModalOutletComponent) {\r\n\t\t\tconst data = parentInstance.modal.data;\r\n\t\t\tconst id = data.id;\r\n\t\t\tconst productName = this.productName = data.productName ? data.productName : this.productName;\r\n\t\t\tconst area = this.area = data.area ? data.area : this.area;\r\n\t\t\tconst countryOfInterestId = this.countryOfInterestId = data.countryOfInterestId ? data.countryOfInterestId : this.countryOfInterestId;\r\n\t\t\tconst agent = this.agent = data.agent;\r\n\t\t\tconsole.log('SalesModalComponent.onInit', id, productName, area, countryOfInterestId, agent);\r\n\t\t}\r\n\t\tthis.error = null;\r\n\t\tthis.success = false;\r\n\t\tthis.response = '';\r\n\t\tthis.message = '';\r\n\t\tconst form = this.form = new FormGroup({\r\n\t\t\tproductName: this.productName,\r\n\t\t\tcountryOfInterest: new FormControl(this.countryOfInterestId),\r\n\t\t\tfirstName: new FormControl(null, [Validators.RequiredValidator()]),\r\n\t\t\tlastName: new FormControl(null, [Validators.RequiredValidator()]),\r\n\t\t\tcompany: new FormControl(null),\r\n\t\t\taddress: new FormControl(null),\r\n\t\t\tcity: new FormControl(null),\r\n\t\t\tzip: new FormControl(null),\r\n\t\t\tcountry: new FormControl(null, [Validators.RequiredValidator()]),\r\n\t\t\temail: new FormControl(null, [Validators.RequiredValidator(), Validators.EmailValidator()]),\r\n\t\t\tsubject: new FormControl(null, [Validators.RequiredValidator()]),\r\n\t\t\tmessage: new FormControl(null, [Validators.RequiredValidator()]),\r\n\t\t\tprivacy: new FormControl(null, [Validators.RequiredTrueValidator()]),\r\n\t\t\tagent: this.agent,\r\n\t\t\tcheckRequest: window.antiforgery,\r\n\t\t\tcheckField: '',\r\n\t\t\taction: 'save_agent_contact',\r\n\t\t});\r\n\t\tconst controls = this.controls = form.controls;\r\n\t\tform.changes$.pipe(\r\n\t\t\ttakeUntil(this.unsubscribe$)\r\n\t\t).subscribe((_) => {\r\n\t\t\tthis.pushChanges();\r\n\t\t});\r\n\t\tthis.load$().pipe(\r\n\t\t\tfirst(),\r\n\t\t).subscribe();\r\n\t}\r\n\r\n\tload$() {\r\n\t\treturn SalesService.data$().pipe(\r\n\t\t\ttap(data => {\r\n\t\t\t\tconst controls = this.controls;\r\n\t\t\t\tcontrols.country.options = FormService.toSelectOptions(data.country.options);\r\n\t\t\t\tthis.pushChanges();\r\n\t\t\t})\r\n\t\t);\r\n\t}\r\n\r\n\ttest() {\r\n\t\tconst form = this.form;\r\n\t\tconst controls = this.controls;\r\n\t\tconst country = controls.country.options.length > 1 ? controls.country.options[1].id : null;\r\n\t\tform.patch({\r\n\t\t\tfirstName: 'Jhon',\r\n\t\t\tlastName: 'Appleseed',\r\n\t\t\tcompany: 'Websolute',\r\n\t\t\taddress: 'Strada della Campanara, 15',\r\n\t\t\tcity: 'Pesaro',\r\n\t\t\tzip: 61122,\r\n\t\t\tcountry: country,\r\n\t\t\temail: 'jhonappleseed@gmail.com',\r\n\t\t\tsubject: 'Subject',\r\n\t\t\tmessage: 'Hi!',\r\n\t\t\tprivacy: true,\r\n\t\t\tcheckRequest: window.antiforgery,\r\n\t\t\tcheckField: ''\r\n\t\t});\r\n\t}\r\n\r\n\treset() {\r\n\t\tconst form = this.form;\r\n\t\tform.reset();\r\n\t}\r\n\r\n\tonSubmit(model) {\r\n\t\tconst form = this.form;\r\n\t\tconsole.log('SalesModalComponent.onSubmit', form.value);\r\n\t\t// console.log('SalesModalComponent.onSubmit', 'form.valid', valid);\r\n\t\tif (form.valid) {\r\n\t\t\t// console.log('SalesModalComponent.onSubmit', form.value);\r\n\t\t\tform.submitted = true;\r\n\t\t\tSalesService.submit$(form.value).pipe(\r\n\t\t\t\tfirst(),\r\n\t\t\t).subscribe(_ => {\r\n\t\t\t\tif (_.success) {\r\n\t\t\t\t\tGtmService.push({ 'event': \"Sales\", 'form_name': \"Contatti\" });\r\n\t\t\t\t}\r\n\t\t\t\tthis.success = true;\r\n\t\t\t\tform.reset();\r\n\t\t\t\tthis.response = _.data[\"response\"];\r\n\t\t\t\tthis.message = _.data[\"message\"];\r\n\t\t\t}, error => {\r\n\t\t\t\tconsole.log('SalesModalComponent.error', error);\r\n\t\t\t\tthis.error = error;\r\n\t\t\t\tthis.pushChanges();\r\n\t\t\t});\r\n\t\t} else {\r\n\t\t\tform.touched = true;\r\n\t\t}\r\n\t}\r\n\r\n\tonClose() {\r\n\t\tModalService.reject();\r\n\t}\r\n}\r\n\r\nSalesModalComponent.meta = {\r\n\tselector: '[sales-modal]',\r\n\tinputs: ['productName', 'countryOfInterestId'],\r\n};\r\n","import { Component, getContext } from 'rxcomp';\r\nimport { fromEvent } from 'rxjs';\r\nimport { startWith, tap } from 'rxjs/operators